body.script:
    const translations = {
      ar: {
        brand: 'ECO-HEALTH 360°',
        navAxes: 'محاور التوعية',
        navMyths: 'صح ولا غلط؟',
        navReport: 'بلّغ عن مشكلة',
        navAssistant: 'اسأل المساعد',
        navResources: 'مصادر موثوقة',
        navCTA: 'ابدأ التوعية',
        eyebrow: '🌱 مبادرة مجتمعية • صحة وبيئة ووعي',
        heroTitle: 'وعي ينقذ حياة،
وبيئة تحمي مستقبلنا.',
        heroText: 'من المعلومة الطبية الموثوقة إلى السلوك الوقائي. مساحة بسيطة تساعدك تفهم صحتك، تميّز المعلومة الصحيحة، وتتعرف على طرق حماية بيئتك ومجتمعك.',
        heroBtn1: 'اكتشف محاورنا ←',
        heroBtn2: 'أبلغ عن مشكلة بيئية',
        stat1b: '6 محاور', stat1s: 'لصحة أفضل',
        stat2b: 'ببساطة', stat2s: 'معلومة مفهومة',
        stat3b: 'معًا', stat3s: 'نشارك ونحمي',
        pillarsKicker: 'OUR SIX PILLARS',
        pillarsTitle: 'ستة محاور… لقرار صحي أذكى',
        pillarsText: 'اختاري الموضوع اللي يهمك، اقرئي الرسالة الأساسية، وشاركيها مع أسرتك ومجتمعك.',
        mythsTitle: 'صح ولا غلط؟',
        mythsText: 'معلومة صغيرة ممكن تغيّر قرارًا كبيرًا. اختبر معلوماتك.',
        quizHeading: 'اختبر نفسك',
        quizQuestion: 'هل يمكن الحكم على سلامة مياه الشرب من شكلها فقط؟',
        goldenRuleHeading: 'قاعدة ذهبية',
        goldenRuleText: 'لو المعلومة بتطلب منك توقف دواء موصوف، أو تستخدم مادة مجهولة، أو تتجاهل عرضًا خطيرًا، ما تعتمدش عليها من غير مراجعة مختص.',
        environmentTitle: 'إزاي نحمي صحتنا من المخاطر البيئية؟',
        environmentText: 'خطوات عملية عامة، مع الرجوع للجهات المختصة عند وجود خطر أو تلوث محتمل.',
        reportTitle: 'شفت مشكلة بيئية؟ ساعدنا نرصدها',
        reportText: 'النموذج التالي نموذج توضيحي لجمع بلاغ تجريبي. في النسخة المنشورة يجب ربطه بجهة مسؤولة عن استقبال البلاغات ومراجعتها.',
        assistantTitle: 'اسأل المساعد التوعوي',
        assistantText: 'جرّب أسئلة عن المياه والنفايات والمبيدات والوعي الصحي. هذه نسخة توضيحية بإجابات إرشادية محدودة وليست خدمة ذكاء اصطناعي متصلة أو بديلًا عن المختص.'
      },
      en: {
        brand: 'ECO-HEALTH 360°',
        navAxes: 'Awareness Areas',
        navMyths: 'Myth or Fact?',
        navReport: 'Report an Issue',
        navAssistant: 'Ask the Assistant',
        navResources: 'Trusted Sources',
        navCTA: 'Start Awareness',
        eyebrow: '🌱 Community initiative • health, environment & awareness',
        heroTitle: 'Awareness saves lives,
and a healthier environment protects our future.',
        heroText: 'From reliable medical information to preventive action. A simple space that helps you understand your health, recognize trustworthy guidance, and protect your environment and community.',
        heroBtn1: 'Explore our pillars →',
        heroBtn2: 'Report an environmental issue',
        stat1b: '6 pillars', stat1s: 'for better health',
        stat2b: 'Simply', stat2s: 'clear information',
        stat3b: 'Together', stat3s: 'we protect each other',
        pillarsKicker: 'OUR SIX PILLARS',
        pillarsTitle: 'Six pillars for a smarter, healthier decision',
        pillarsText: 'Choose the topic that matters to you, read the core message, and share it with your family and community.',
        mythsTitle: 'Myth or fact?',
        mythsText: 'A small fact can change a big decision. Test your knowledge.',
        quizHeading: 'Test yourself',
        quizQuestion: 'Can you judge the safety of drinking water just by its appearance?',
        goldenRuleHeading: 'Golden rule',
        goldenRuleText: 'If the information asks you to stop a prescribed medicine, use an unknown substance, or ignore a serious symptom, do not rely on it without consulting a professional.',
        environmentTitle: 'How can we protect our health from environmental risks?',
        environmentText: 'Practical general steps, while consulting relevant authorities when a possible danger or contamination is suspected.',
        reportTitle: 'Saw an environmental problem? Help us monitor it',
        reportText: 'This form is an illustrative example for collecting a test report. In the published version, it should be connected to a proper reporting authority.',
        assistantTitle: 'Ask the awareness assistant',
        assistantText: 'Try questions about water, waste, pesticides, and health awareness. This is a limited educational demo and not a real connected AI service or substitute for a professional.'
      }
    };

    let currentLang = 'ar';

    function applyTranslations(lang) {
      currentLang = lang;
      const nodes = document.querySelectorAll('[data-i18n]');
      nodes.forEach(node => {
        const key = node.dataset.i18n;
        if (translations[lang] && translations[lang][key]) {
          node.innerHTML = translations[lang][key];
        }
      });
      document.documentElement.lang = lang;
      document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
      document.getElementById('langToggle').textContent = lang === 'ar' ? 'EN' : 'AR';
    }

    document.getElementById('langToggle').addEventListener('click', () => {
      applyTranslations(currentLang === 'ar' ? 'en' : 'ar');
    });

    function answerQuiz(correct) {
      const box = document.getElementById('quizResult');
      box.style.display = 'block';
      box.textContent = correct
        ? 'إجابة صحيحة! صفاء المياه لا يكفي للحكم على سلامتها؛ نحتاج مصدرًا موثوقًا وفحصًا مناسبًا.'
        : 'مش بالضرورة. ممكن المياه تبدو صافية ومع ذلك تحتوي على ملوثات لا تُرى بالعين.';
    }

    document.getElementById('reportForm').addEventListener('submit', function (e) {
      e.preventDefault();
      const type = document.getElementById('type').value;
      const place = document.getElementById('place').value.trim();
      const desc = document.getElementById('desc').value.trim();
      const box = document.getElementById('reportSuccess');
      box.style.display = 'block';
      box.textContent = 'ملخص تجريبي (لم يتم إرساله): نوع المشكلة: ' + type + ' | المنطقة: ' + place + ' | الوصف: ' + desc;
    });

    function addBubble(text, kind) {
      const log = document.getElementById('chatlog');
      const bubble = document.createElement('div');
      bubble.className = 'bubble ' + kind;
      bubble.textContent = text;
      log.appendChild(bubble);
      log.scrollTop = log.scrollHeight;
    }

    function getLocalFallback(question) {
      const q = question.toLowerCase();
      if (q.includes('مياه') || q.includes('ماء') || q.includes('شرب') || q.includes('صافي')) {
        return 'صفاء المياه لا يثبت سلامتها. استخدم مصدرًا مأمونًا، وخزّن المياه في وعاء نظيف ومغطى. الغلي قد يساعد ضد كثير من الميكروبات لكنه لا يزيل الملوثات الكيميائية. عند الشك، تواصل مع جهة المياه أو معمل معتمد للفحص.';
      }
      if (q.includes('مبيد') || q.includes('عبوة') || q.includes('كيما')) {
        return 'اتبع تعليمات ملصق المنتج والجهات المختصة. أبعد المبيدات عن الأطفال والطعام، ولا تنقلها إلى عبوات مشروبات أو تعيد استخدام العبوة الفارغة. لا تخلط مواد كيميائية. عند التعرض أو ظهور أعراض، ابتعد عن المصدر واطلب مساعدة طبية/مركز السموم فورًا.';
      }
      if (q.includes('قمامة') || q.includes('حرق') || q.includes('نفايات') || q.includes('مخلفات')) {
        return 'تجنب حرق القمامة أو البلاستيك؛ الدخان قد يضر الجهاز التنفسي. لا تلمس النفايات الحادة أو المجهولة. استخدم نظام الجمع المحلي، وأبلغ الجهة المختصة عن التراكم أو الحرق.';
      }
      if (q.includes('طبيب') || q.includes('مساعدة') || q.includes('أعراض') || q.includes('مرض')) {
        return 'اطلب تقييمًا طبيًا عند الأعراض المستمرة أو المقلقة. صعوبة التنفس الشديدة، ألم الصدر الشديد، فقدان الوعي أو علامات السكتة تستدعي الطوارئ فورًا. لا تعتمد على المساعد لتشخيص الحالة.';
      }
      return 'أقدر أساعد بمعلومات توعوية عامة عن المياه والنفايات والمبيدات وتلوث الهواء. اكتب سؤالك بصورة أوضح، وتحقق دائمًا من الإرشادات الرسمية؛ هذه النسخة ليست مساعد AI متصلًا ولا تقدم تشخيصًا.';
    }

    async function getAiReply(question) {
      const apiKey = localStorage.getItem('eco_health_ai_key') || '';
      if (apiKey) {
        try {
          const response = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': 'Bearer ' + apiKey
            },
            body: JSON.stringify({
              model: 'gpt-4o-mini',
              messages: [{
                role: 'system',
                content: 'You are a helpful community health and environmental awareness assistant in Arabic. Give brief, safe, non-diagnostic advice, mention to consult licensed professionals, and avoid medical diagnoses.'
              }, { role: 'user', content: question }],
              temperature: 0.6
            })
          });

          if (response.ok) {
            const data = await response.json();
            const content = data?.choices?.[0]?.message?.content;
            if (content && content.trim()) return content.trim();
          }
        } catch (err) {
          console.warn('AI API call failed, using fallback:', err);
        }
      }
      return getLocalFallback(question);
    }

    function saveApiKey() {
      const input = document.getElementById('apiKeyInput');
      const key = input.value.trim();
      if (!key) {
        localStorage.removeItem('eco_health_ai_key');
        addBubble('تم حذف مفتاح الذكاء الاصطناعي. الآن سيتم استخدام الردود المحلية.', 'bot');
        return;
      }
      localStorage.setItem('eco_health_ai_key', key);
      addBubble('تم حفظ مفتاح الذكاء الاصطناعي بنجاح. يمكنك الآن تجربة أسئلة حقيقية.', 'bot');
    }

    async function sendChat() {
      const input = document.getElementById('chatInput');
      const question = input.value.trim();
      if (!question) return;
      addBubble(question, 'user');
      input.value = '';
      const answer = await getAiReply(question);
      addBubble(answer, 'bot');
    }

    function askQuick(q) {
      const input = document.getElementById('chatInput');
      input.value = q;
      sendChat();
    }

    document.getElementById('chatInput').addEventListener('keydown', (e) => {
      if (e.key === 'Enter') sendChat();
    });

    applyTranslations('ar');
    const savedKey = localStorage.getItem('eco_health_ai_key');
    if (savedKey) document.getElementById('apiKeyInput').value = savedKey;
